# Own-wording items of Exploring Eberron (2024). Row shape as tdcsr_item.py: [name, type, rarity, attune, text, opts].
# This book has no baseitem. Weapons and armor are plain items, so the few weapons carry WPN or base.
# Item groups (Blast Disk, Channeling Wand, Coat of Many Eyes, Dragonmark Channel, Dragonmark Reservoir, Houseward) are covered by their members.
# Magic variants (Bane, Byeshk, Hungry, Resistance Breaker, Silent, +1/+2/+3 Tools of the Master) are generic rows at the end.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
MASTERY = {}
WDESC = {}

def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

SYM = " **Symbiotic.** Once you attune to it, you cannot remove it unless Remove Curse or similar magic targets you."

# ---- Spells of the Mark: level -> spells
MARKS = {
 "Detection": {1: ["Detect Evil and Good", "Identify"], 2: ["Detect Thoughts", "Find Traps"], 3: ["Clairvoyance", "Nondetection"], 4: ["Arcane Eye", "Divination"], 5: ["Legend Lore"]},
 "Finding": {1: ["Faerie Fire", "Longstrider"], 2: ["Locate Animals or Plants", "Mind Spike"], 3: ["Clairvoyance", "Speak with Plants"], 4: ["Divination", "Locate Creature"], 5: ["Commune with Nature"]},
 "Handling": {1: ["Command", "Find Familiar"], 2: ["Beast Sense", "Calm Emotions"], 3: ["Beacon of Hope", "Conjure Animals"], 4: ["Aura of Life", "Dominate Beast"], 5: ["Awaken"]},
 "Healing": {1: ["False Life", "Healing Word"], 2: ["Arcane Vigor", "Prayer of Healing"], 3: ["Aura of Vitality", "Mass Healing Word"], 4: ["Aura of Life", "Aura of Purity"], 5: ["Greater Restoration"]},
 "Hospitality": {1: ["Goodberry", "Sleep"], 2: ["Aid", "Enhance Ability"], 3: ["Create Food and Water", "Leomund's Tiny Hut"], 4: ["Aura of Purity", "Mordenkainen's Private Sanctum"], 5: ["Hallow"]},
 "Making": {1: ["Identify", "Tenser's Floating Disk"], 2: ["Continual Flame", "Spiritual Weapon"], 3: ["Conjure Barrage", "Elemental Weapon"], 4: ["Fabricate", "Stone Shape"], 5: ["Creation"]},
 "Passage": {1: ["Expeditious Retreat", "Jump"], 2: ["Find Steed", "Pass without Trace"], 3: ["Blink", "Phantom Steed"], 4: ["Dimension Door", "Freedom of Movement"], 5: ["Teleportation Circle"]},
 "Scribing": {1: ["Command", "Illusory Script"], 2: ["Animal Messenger", "Silence"], 3: ["Sending", "Tongues"], 4: ["Arcane Eye", "Confusion"], 5: ["Dream"]},
 "Sentinel": {1: ["Compelled Duel", "Shield of Faith"], 2: ["Warding Bond", "Zone of Truth"], 3: ["Counterspell", "Protection from Energy"], 4: ["Death Ward", "Guardian of Faith"], 5: ["Bigby's Hand"]},
 "Shadow": {1: ["Disguise Self", "Silent Image"], 2: ["Darkness", "Pass without Trace"], 3: ["Clairvoyance", "Major Image"], 4: ["Greater Invisibility", "Hallucinatory Terrain"], 5: ["Mislead"]},
 "Storm": {1: ["Feather Fall", "Fog Cloud"], 2: ["Levitate", "Shatter"], 3: ["Sleet Storm", "Wind Wall"], 4: ["Conjure Minor Elementals", "Control Water"], 5: ["Conjure Elemental"]},
 "Warding": {1: ["Armor of Agathys", "Sanctuary"], 2: ["Knock", "Nystul's Magic Aura"], 3: ["Glyph of Warding", "Magic Circle"], 4: ["Leomund's Secret Chest", "Mordenkainen's Faithful Hound"], 5: ["Antilife Shell"]},
}
for _m, _L in MARKS.items():
    _by = "Mark of " + _m
    _w = "%s Channeling Wand" % _m; _c = "%s Dragonmark Channel" % _m; _r = "%s Dragonmark Reservoir" % _m
    add(_w, "Wand", "Rare", 1,
        "Requires the Mark of %s. The wand has 7 charges. Cast any Mark of %s spell from it by spending charges equal to the spell's level, using your Dragonmark feat's spellcasting ability. Spend extra to enhance a spell: 2 charges to cast a 1-Magic-action spell as a Bonus Action, 1 to double the duration (max 24 hours), or 1 to double the range (Touch becomes 30 ft). It regains 1d6 + 1 charges at dawn. If you spend the last charge, roll 1d20 and on a 1 the wand turns to ash." % (_m, _m),
        by=_by, ch=[7, "1d6+1", "dawn"])
    SP[_w] = {"sp": [[s, l] for l in sorted(_L) for s in _L[l]]}
    add(_c, "Wondrous Item", "Common", 1,
        "Requires the Mark of %s. A brooch set with a Siberys dragonshard. Cast any level 1 Mark of %s spell from it, using your Dragonmark feat's spellcasting ability. It cannot be used again until you finish a Long Rest." % (_m, _m),
        by=_by, ch=[1, "1", "long"])
    SP[_c] = {"sp": [[s, 1] for s in _L[1]]}
    add(_r, "Wondrous Item", "Uncommon", 1,
        "Requires the Mark of %s. A dragonshard amulet or bracelet with 7 charges. Cast any Mark of %s spell of level 1 or 2 from it by spending charges equal to the spell's level, using your Dragonmark feat's spellcasting ability. It regains 1d6 + 1 charges at dawn." % (_m, _m),
        by=_by, ch=[7, "1d6+1", "dawn"])
    SP[_r] = {"sp": [[s, l] for l in (1, 2) for s in _L[l]]}

# ---- Blast Disk (three rarities)
def _bd(rar, pay):
    add("Blast Disk (%s)" % rar, "Wondrous Item", rar, 0,
        "A 9-inch metal disk of dragonshards and arcane engravings. A spellcaster activates it with a Magic action and picks the trigger when it is made: Time (delay up to 10 minutes), Proximity (arms after 30 seconds) or Impact (when thrown or dropped). " + pay +
        " It has one charge, so the shards shatter on use. A version that recharges at dawn is one rarity higher. An Intelligence (Arcana) check against the save DC identifies the effect. Disarming needs proficiency in Arcana and a Dexterity check with Thieves' Tools against the save DC, and failing by 5 or more sets it off.")
_bd("Common", "**Explosive.** A 20-ft-radius Sphere around the disk. Dexterity save DC 13, 11 (2d10) damage of a type set at creation on a fail or half on a success. Objects and structures take triple.")
_bd("Uncommon", "**Spell effect.** Holds a level 1 to 3 spell that targets whoever triggers it or an area around the disk. Save DC 14, spell attack bonus +6.")
_bd("Rare", "**Spell effect.** Holds a level 4 or 5 spell that targets whoever triggers it or an area around the disk. Save DC 16, spell attack bonus +8.")

# ---- Coat of Many Eyes
_coat = "Armor made by the daelkyr Belashyrra, covered with watching eyes. When you attune, it binds to your flesh. You gain Darkvision 120 ft, see in all directions, and have Advantage on sight-based Wisdom (Perception) checks. Visions from Belashyrra may ask for tasks, and completing them can raise the coat's rarity."
add("Coat of Many Eyes (Uncommon)", "Armor", "Uncommon", 1, _coat + SYM, fx={"dark": 120}, base=["Studded Leather Armor"], by="Service to Belashyrra")
add("Coat of Many Eyes (Rare)", "Armor", "Rare", 1, _coat + " **Rare.** +1 bonus to AC and you see Invisible creatures and objects within 120 ft." + SYM, fx={"ac": 1, "dark": 120}, base=["Studded Leather Armor"], by="Service to Belashyrra")
add("Coat of Many Eyes (Very Rare)", "Armor", "Very Rare", 1, _coat + " **Very Rare.** +1 bonus to AC, you see Invisible creatures and objects within 120 ft, and you can cast Arcane Eye with a Magic action (once per Long Rest)." + SYM, fx={"ac": 1, "dark": 120}, base=["Studded Leather Armor"], ch=[1, "1", "long"], by="Service to Belashyrra")
SP["Coat of Many Eyes (Very Rare)"] = {"sp": [["Arcane Eye", 0]]}

# ---- Houseward
for _r, _a in (("Uncommon", "2,500"), ("Rare", "5,000"), ("Legendary", "10,000")):
    add("Houseward (%s)" % _r, "Wondrous Item", _r, 0,
        "Requires the Mark of Warding. A 1-cubic-foot lead block with a Siberys dragonshard, usually set into a floor. A creature with the Mark of Warding that touches it for 10 minutes casts Guards and Wards from it with no Material components, protecting %s square feet. The spell lasts 24 days but ends early if the Houseward casts it again, a Mark of Warding creature touches it for 10 minutes to end it, or the block leaves the protected area. It cannot cast again until the next dawn." % _a,
        ch=[1, "1", "dawn"])
    SP["Houseward (%s)" % _r] = {"sp": [["Guards and Wards", 0]]}

# ---- other Dragonmark items
add("Manor Key", "Wondrous Item", "Rare", 0, "Requires the Mark of Hospitality. A long key studded with tiny dragonshards. With a Magic action, trace a door in the air to cast Mordenkainen's Magnificent Mansion with no Material components. The spell ends after 24 hours or when you lock the door and dismiss it, and anyone inside is expelled near the entrance. It cannot be used again until the next dawn.", ch=[1, "1", "dawn"])
SP["Manor Key"] = {"sp": [["Mordenkainen's Magnificent Mansion", 0]]}
add("Helm of the Sentinel", "Wondrous Item", "Rare", 1, "Requires the Mark of Sentinel. The helm has 3 charges and regains all of them at dawn. **Counterspell.** Magic action, 1 charge: set a ward. The next time you see an unfriendly creature within 60 ft cast a spell that targets you or forces you to save, Counterspell takes effect as if you cast it with your Reaction. Wisdom is the ability. The ward ends after it triggers or at the next dawn. **Protection.** Magic action, 1 charge: cast Protection from Energy on yourself. **Deflection Field.** Bonus Action, 1 charge: cast Shield of Faith on yourself.", by="Mark of Sentinel", ch=[3, "all", "dawn"])
SP["Helm of the Sentinel"] = {"sp": [["Counterspell", 1], ["Protection from Energy", 1], ["Shield of Faith", 1]]}
add("Prospector's Wand", "Wand", "Uncommon", 1, "Requires the Mark of Finding. The wand has 5 charges and regains 1d4 + 1 at dawn. **Finding.** 2 charges: cast Locate Creature. **Location.** 1 charge: cast Locate Object. **Prospecting.** 1 charge: cast Locate Animals or Plants, and you can name a mineral instead of a Beast or Plant and set a minimum quantity to find within 30 ft of radius. If you spend the last charge, roll 1d20 and on a 1 the wand turns to ash.", by="Mark of Finding", ch=[5, "1d4+1", "dawn"])
SP["Prospector's Wand"] = {"sp": [["Locate Creature", 2], ["Locate Object", 1], ["Locate Animals or Plants", 1]]}
add("Rod of Wild Dominion", "Rod", "Rare", 1, "Requires the Mark of Handling. A varnished oak rod capped with dragonshards. **Dominion.** Cast Dominate Beast from it with a duration of up to 1 hour. Wisdom is the ability, and it cannot be used again until the next dawn. **Handling.** Advantage on Wisdom (Animal Handling) and Wisdom (Survival) checks. **Wild Speech.** Cast Speak with Animals from it at will.", by="Mark of Handling", ch=[1, "1", "dawn", "Uses for Dominate Beast"])
SP["Rod of Wild Dominion"] = {"sp": [["Speak with Animals", 0], ["Dominate Beast", 1]]}
add("Ghallanda Cauldron", "Wondrous Item", "Common", 1, "Requires the Mark of Hospitality. A cauldron etched with sigils that can heat, chill or flavor its contents, even copying spices you lack. Cooking in it takes 90 percent less time, and you have Advantage on ability checks with Cook's Utensils.", by="Mark of Hospitality")

# ---- Dragonmark house items that copy standard items
add("Cloak of Passage", "Wondrous Item", "Uncommon", 0, "A cloak that smells faintly of brimstone. With a Magic action you can cast Dimension Door from it. It cannot do so again until the next dawn. When the spell moves you, a puff of smoke remains where you were, Lightly Obscuring that space until your next turn ends.", ch=[1, "1", "dawn"])
SP["Cloak of Passage"] = {"sp": [["Dimension Door", 0]]}
add("Cloak of Shadows", "Wondrous Item", "Common", 1, "Requires the Mark of Shadow. You have Advantage on Dexterity (Stealth) checks, and a creature making a Wisdom (Perception) check to notice you has Disadvantage.", by="Mark of Shadow")
add("Deni Shield", "Armor", "Common", 0, "An eye symbol marks this Shield. While you hold it, you roll Initiative with Advantage and have Advantage on Wisdom (Perception) checks.", base=["Shield"])
add("Eyes of the Dragonne", "Wondrous Item", "Common", 0, "Crystal lenses worn over the eyes. You have Advantage on sight-based Wisdom (Perception) checks, and in clear visibility you can pick out details as small as 2 ft across at great distance.")
add("Ghallan Jug", "Wondrous Item", "Common", 0, "A 12-pound ceramic jug. With a Magic action, name one liquid and it starts making it: acid (8 oz), basic poison (4 oz), beer (4 gal), honey (1 gal), mayonnaise (2 gal), oil (1 quart), vinegar (2 gal), fresh water (8 gal), salt water (12 gal) or wine (1 gal). A Utilize action uncorks it to pour up to 2 gallons per minute. Once it makes a liquid, it cannot switch.")
add("Jora Charm", "Wondrous Item", "Common", 1, "Requires the Mark of Healing. **Life Preservation.** When you roll a 9 or lower on a Death Saving Throw, treat it as a 10. **Natural Healing Boost.** Each Hit Point Die you roll to heal yourself restores twice the normal Hit Points.", by="Mark of Healing")
add("Kundar Chains", "Wondrous Item", "Uncommon", 0, "A Utilize action locks these shackles on an Incapacitated creature, and they resize to fit Small to Large. The bound creature cannot use extradimensional movement such as teleportation or plane travel, though it can pass through a portal. You and creatures you name can remove them with a Utilize action. The bound creature can try a DC 30 Strength (Athletics) check once every 30 days, and on a success it breaks free and the shackles are destroyed.")
add("Medani Dowser", "Wand", "Common", 0, "The wand has 3 charges and regains 1d3 at dawn. With a Magic action and 1 charge, if a secret door or trap is within 60 ft, the wand points to the nearest one.", ch=[3, "1d3", "dawn"])
add("Medi Spectacles", "Wondrous Item", "Common", 0, "Crystal lenses worn over the eyes. Within 1 ft you have Darkvision and Advantage on Intelligence (Investigation) checks to examine something.")
add("Ori Boots", "Wondrous Item", "Uncommon", 1, "Requires the Mark of Passage. As a Bonus Action, click the heels to double your Speed and give Opportunity Attacks against you Disadvantage. Clicking again ends it. After 10 total minutes of use, the boots stop working until you finish a Long Rest.", by="Mark of Passage")
add("Serpentine Mirror", "Wondrous Item", "Rare", 1, "Requires the Mark of Shadow. While you touch this mirror, you can cast Scrying from it (save DC 17).", by="Mark of Shadow")
SP["Serpentine Mirror"] = {"sp": [["Scrying", 0]], "dc": 17}
add("Storm's Embrace", "Ring", "Uncommon", 1, "Requires the Mark of Storm. When you fall while wearing this ring, you descend 60 ft per round and take no damage from the fall.", by="Mark of Storm")
add("Thuranni Cloak", "Wondrous Item", "Uncommon", 1, "Requires the Mark of Shadow. An illusion makes you appear to stand near your true spot, so attack rolls against you have Disadvantage. The effect pauses until your next turn starts when you take damage, and while your Speed is 0.", by="Mark of Shadow")
add("Vadalis Band", "Wondrous Item", "Uncommon", 0, "A ring with 3 charges that regains 1d3 at dawn. Spend 1 charge to cast Animal Friendship, Fear (Beasts only) or Speak with Animals from it, with save DC 13.", ch=[3, "1d3", "dawn"])
SP["Vadalis Band"] = {"sp": [["Animal Friendship", 1], ["Fear", 1], ["Speak with Animals", 1]], "dc": 13}
add("Warding Brooch", "Wondrous Item", "Common", 1, "Requires the Mark of Warding. You have Resistance to Force damage and Immunity to damage from Magic Missile.", by="Mark of Warding", fx={"res": ["Force"]})
add("Wind Stones", "Wondrous Item", "Common", 0, "A pair of carved stones. While touching one, you can cast Sending from it, and the target is whoever holds the other stone. If no one holds it, you learn that and do not cast. After either stone is used, neither works again until the next dawn. If one stone is destroyed, the other loses its magic.", ch=[1, "1", "dawn"])
SP["Wind Stones"] = {"sp": [["Sending", 0]]}
add("Cannith's Marvelous Miniatures", "Wondrous Item", "Uncommon", 0, "A feather-like token with one use. With a Magic action, throw it 5 ft upward and it becomes a huge multicolored bird using Roc statistics but unable to attack. It follows simple commands and carries 500 lb at 16 mph (144 miles per day, resting 1 hour per 3 of flight) or 1,000 lb at half speed. It vanishes after its daily maximum or at 0 Hit Points, or when you dismiss it with a Magic action.")

# ---- common and uncommon wondrous items
add("Aereni Mask", "Wondrous Item", "Uncommon", 1, "A mask tied to an Aereni noble line, and its ancestor spirits must judge you worthy before you can attune. It is made with two skills. When you make an ability check with either skill, roll 1d4 and add it to the check.", by="Worthy bearer")
add("Battle Rod", "Rod", "Common", 0, "Held in two hands, it lets you cast cantrips at up to twice their range. A cantrip cast beyond its normal range has Disadvantage on attack rolls and gives targets Advantage on saves. For example, Fire Bolt reaches 240 ft but attacks past 120 ft have Disadvantage.")
add("Breath of Siberys", "Wondrous Item", "Common", 0, "A small globe of refined dragonshard solution used to prime arcane artillery in place of a spell slot. With a Magic action, dissolve it on a staff's charging plate to restore 1d4 charges to that staff.")
add("Charlatan's Gloves", "Wondrous Item", "Common", 0, "With a Magic action, create a palm-sized illusory image that lasts 1 minute or until your Concentration ends. It has no sound, light, smell or other sense effect, and things pass through it. A creature can use a Study action for an Intelligence (Investigation) check contested by your Charisma (Deception), and on a success the image becomes faint to it.")
add("Drybrooch", "Wondrous Item", "Common", 0, "Held or worn, it lets you summon or dismiss, with a Magic action, an energy dome over your head that repels rain, snow and similar nuisances. It does not protect against harsh hazards or attacks.")
add("Duster", "Wand", "Common", 0, "With a Magic action while holding it, clean dirt and grime from an area within 10 ft of you that is no larger than 1 cubic foot.")
add("Lamplighter", "Wand", "Common", 0, "With a Magic action while holding it, light or snuff a candle, torch, small campfire or similar flame within 10 ft of you.")
add("Talking Wand", "Wand", "Common", 0, "While you hold it, your voice and other sounds you make are three times as loud as normal.")
add("Spark", "Wondrous Item", "Common", 0, "A small stone engraved with Fernian glyphs. While holding it, use a Bonus Action to touch a candle, torch, small campfire or similar object and ignite it.")
add("Thurimbar Rod", "Wondrous Item", "Common", 0, "A magical Musical Instrument from Zilargo. With a Magic action, produce sounds of any instrument you are proficient with, like Minor Illusion, coming from the rod. Make a Charisma check with the replicated instrument to judge the performance. If you are proficient with the rod, you can produce unearthly music.")
add("Uul'kur (Dream Key)", "Wondrous Item", "Common", 0, "An iron token inlaid with a dragonshard sliver. Sleeping with it keeps you lucid in dreams and you remember them clearly. If you understand it, a Magic action binds it to your dreams until the next dawn, and any creature sleeping with it shares your dream.")
add("Vola'khesh", "Wondrous Item", "Common", 0, "A carved stone worn on a strap, made in linked sets of up to ten that cannot be changed later. While wearing one, use a Bonus Action to whisper a message that all wearers of linked stones within 120 ft hear. Magical silence, 1 ft of stone, 1 inch of common metal or 3 ft of wood blocks it, but it bends around corners and openings. Items made as Kra'uul travel with you into Dal Quor when you dream.")
add("Quiver of Energy", "Wondrous Item", "Uncommon", 0, "Whenever you finish a Long Rest, choose Cold, Fire, Lightning or Poison. The first time each turn you hit with a weapon attack using ammunition from this quiver, it deals an extra 1d6 damage of that type.")
add("Gloves of Storing", "Wondrous Item", "Uncommon", 0, "Each glove holds one object of 20 lb or less that fits in one hand. While wearing them, use a Bonus Action to store an object you hold, or a Bonus Action to summon a stored object into an empty hand. A pierced or torn glove is destroyed and its contents scatter in the Astral Plane. Placing them in a Bag of Holding, Portable Hole or similar extradimensional space destroys both and opens a gate to the Astral Plane that pulls in creatures within 10 ft not behind Cover.")
add("Soarsled", "Wondrous Item", "Uncommon", 0, "A crystal disk 5 ft across that carries up to 400 lb. In Sharn or another Syranian manifest zone, stand on it and use a Magic action to make it hover. Once per turn, mentally move it up to 30 ft, and each turn a Magic action and a DC 12 Dexterity (Acrobatics) check moves it 60 ft more on a success. Outside a manifest zone it activates only once. After 10 minutes of flight or when you step off, it cannot be used again until it spends 8 hours in a manifest zone.")
add("Final Messenger", "Wondrous Item", "Uncommon", 0, "Requires use by a Warforged. A Tiny Construct homunculus with AC 20, 6 Hit Points and a Fly Speed of 60 ft. It is immune to Poison and Psychic damage and to all conditions except Unconscious, treats ability scores as 10, has Darkvision 60 ft, and can only Dash. A Warforged can integrate it with a Magic action (one at a time), and then it cannot be targeted by attacks. Detached, it stays active 8 hours, then is Unconscious until it completes a rest attached, which also restores its Hit Points. It holds a destination, a target, one image and a message of up to 25 words, changed with a Magic action. Release it with a Bonus Action. At 0 Hit Points of the wearer it detaches and goes to its target.")
add("Integrated Tool", "Wondrous Item", "Common", 0, "Requires use by a Warforged. Attach a tool of 10 lb or less (Artisan's Tools, Forgery Kit, Herbalism Kit, Poisoner's Kit, Thieves' Tools or a Musical Instrument) to your body over 1 hour. It cannot be removed against your will while you live, though you still need a free hand to use it. You can have only one attached at a time. The DM may allow other species to combine warforged component items with a Prosthetic Limb.")

# ---- symbionts (daelkyr)
add("Crawling Gauntlet", "Wondrous Item", "Uncommon", 1, "Made by the daelkyr, it fuses to your hand and forearm. Your Unarmed Strikes can slash with talons for Slashing damage of 1d6 plus your Strength modifier instead of the normal damage. With a Magic action you can cast Mage Hand from it." + SYM)
SP["Crawling Gauntlet"] = {"sp": [["Mage Hand", 0]]}
add("Shadow Sibling", "Wondrous Item", "Rare", 1, "A black jewel that fuses to your forehead. As a Bonus Action, extend or retract a shadow that hides you. While it is active, Wisdom (Perception) checks to see you have Disadvantage and you have Advantage on Dexterity (Stealth) checks to Hide. When you are hit by an attack, use your Reaction and expend one Hit Die, roll it and add the result to your AC until the end of your next turn, including against the triggering attack." + SYM)
add("Spellburrow", "Wondrous Item", "Uncommon", 1, "A scarab that burrows through your skull to link with your mind when you attune. It knows one cantrip of the DM's choice from the Sorcerer or Warlock list, plus one level 1 and one level 2 spell from that same list. You cast the cantrip as if you know it. If you have Spellcasting or Pact Magic, you cast the other two as if prepared, without counting against your prepared spells. You can use Intelligence or another spellcasting ability you have for them." + SYM)
add("Throwing Scarab", "Wondrous Item", "Uncommon", 1, "A symbiont that fuses to your palm. For each attack in your Attack action, extrude a chitin shard into your empty hand and use it. It counts as a magical Simple Melee weapon you are proficient with, with Finesse, Light and Thrown (range 20/60 ft). It deals 1d4 Piercing plus 1d4 Acid damage and dissolves when it hits or misses." + SYM)
add("Tongueworm", "Wondrous Item", "Uncommon", 1, "A worm that nests under your tongue. As a Bonus Action, make an Unarmed Strike with it using Strength or Dexterity. On a hit it deals Piercing damage of 1d4 plus that modifier instead of the normal damage, and the target must succeed on a DC 13 Constitution save or have the Poisoned condition until the start of your next turn." + SYM)
add("Wandering Eye", "Wondrous Item", "Uncommon", 1, "A tentacle ending in an eye that burrows into your shoulder. While uncovered, it gives these benefits. **Always Vigilant.** It stays watchful during a Long Rest so you use your passive Wisdom (Perception) to notice threats, and a nightmare wakes you if it spots danger. **Periscopic Vision.** It can extend 18 inches to look around corners or cover. Then it has AC 20 and 6 Hit Points and uses your statistics for checks and saves. At 0 Hit Points you lose its benefits until a Short or Long Rest. **Third Eye.** Roll 1d4 and add it to Wisdom (Perception) or Intelligence (Investigation) checks involving sight." + SYM)

# ---- artifact and rare weapon/armor
add("Ghaal'duur, the Mighty Dirge", "Wondrous Item", "Artifact", 1, "A three-foot Dhakaan warhorn that only a Bard can attune to. It has 2 minor beneficial and 1 minor detrimental random artifact properties (a goblinoid is immune to the detrimental one). **Jhazaal's Presence.** Your Charisma increases by 4, to a maximum of 24. **The Dragon's Song.** Held in both hands as a Spellcasting Focus, your Bard spells have doubled duration if 1 minute or longer (max 24 hours), doubled range if 5 ft or more, and are cast as one slot level higher. **The Sound of Victory.** Magic action, both hands: for 10 minutes, allies within 600 ft who hear you add 1d4 (2d4 for goblinoids) to attack rolls and saves. Each enemy within 600 ft that hears you makes a Charisma save against your Bard spell save DC, and on a fail subtracts 1d4 (2d4 for goblinoids) from attack rolls and saves. Once used, it returns after a Short or Long Rest. Only the fire of the dragon Jharaashta can destroy it.", by="Bard", fx={"abil": ["CHA", 4, 24]}, ch=[1, "1", "short"])
add("Breastplate of Kamvuul Norek", "Armor", "Legendary", 1, "Adamantine Breastplate of a hobgoblin Aberration slayer. You gain a +2 bonus to AC, a Critical Hit against you becomes a normal hit, and you have Advantage on saving throws against spells and other magical effects. If you succeed on a save against Mind Blast or a similar Aberration cone, you are unaffected and the effect reflects back at the Aberration as if the cone started from you.", fx={"ac": 2}, base=["Breastplate"])
add("Keeper's Fang", "Weapon", "Rare", 0, "A dagger with a Khyber dragonshard in its pommel. You gain a +1 bonus to attack and damage rolls with it. When you reduce a creature to 0 Hit Points with it, the creature is slain and its soul removed, and only a Wish spell can restore it.", fx={"atk": 1, "dmg": 1}, base=["Dagger"])
add("Shaarat'doovol, the Blade of Truth", "Weapon", "Legendary", 1, "A sentient longsword forged below Sharn. You gain a +3 bonus to attack and damage rolls with it, and a hit on an Aberration deals an extra 2d10 Radiant damage. **Unyielding Duty.** If it favors you, while you wield it you gain Truesight 90 ft, Immunity to the Charmed and Frightened conditions, and Resistance to Psychic damage.", fx={"atk": 3, "dmg": 3, "res": ["Psychic"], "condImm": ["Charmed", "Frightened"]}, base=["Longsword"], xd=["Aberration: +2d10 Radiant"])
add("War Staff", "Weapon", "Common", 1, "A staff of 1d6 Bludgeoning (1d8 Versatile) with Topple mastery, held in both hands as an Arcane Focus. Cantrips cast through it have up to four times their normal range. Beyond twice the normal range, your attack rolls have Disadvantage and targets have Advantage on saves. For example, Fire Bolt reaches 480 ft but attacks past 240 ft have Disadvantage.", by="Spellcaster")
WPN["War Staff"] = {"d": "1d6", "t": "Bludgeoning", "cat": "S", "k": "M", "p": "Versatile (1d8)", "m": "Topple", "w": 4, "xw": 1}
add("Grieving Tree", "Wondrous Item", "Unknown", 0, "A giant white marble skeletal tree weighing thousands of pounds, a lost prison and torture device. Attunement requires rediscovering its lost techniques. It holds up to four prisoners and has a Lingering Life pool that starts at 20 Hit Points and grows to a maximum of 200. When a prisoner would be left at 0 Hit Points alive, it heals 1d4 + 1 from the pool. A creature within 5 ft can free a prisoner with a DC 20 Strength (Athletics) check, and both take 3d6 Piercing damage on any attempt. While attuned and within 120 ft, you can use these Magic actions. **Grab.** A target within 20 ft makes a DC 24 Dexterity save or is captured, takes 6d6 Piercing damage and is Stunned until released. **Eviscerate.** All Stunned creatures take 8d6 Piercing damage and half the total goes to the pool. **Answer for Their Crimes.** Cast Speak with Dead on a prisoner's corpse, which must speak truthfully. **Release a Prisoner.** A Bonus Action frees one.", by="Lost techniques")
SP["Grieving Tree"] = {"sp": [["Speak with Dead", 0]]}

# ---- magic variants (generic rows)
add("+1 Tools of the Master", "Wondrous Item", "Uncommon", 1, "A magic Artisan's Tool. You must be proficient with it to attune. Using it as a Spellcasting Focus gives a +1 bonus to spell attack rolls. You can add the same bonus to any ability check made with this tool.", fx={"spellAtk": 1}, by="Proficiency with the tool")
add("+2 Tools of the Master", "Wondrous Item", "Rare", 1, "A magic Artisan's Tool. You must be proficient with it to attune. Using it as a Spellcasting Focus gives a +2 bonus to spell attack rolls. You can add the same bonus to any ability check made with this tool.", fx={"spellAtk": 2}, by="Proficiency with the tool")
add("+3 Tools of the Master", "Wondrous Item", "Very Rare", 1, "A magic Artisan's Tool. You must be proficient with it to attune. Using it as a Spellcasting Focus gives a +3 bonus to spell attack rolls. You can add the same bonus to any ability check made with this tool.", fx={"spellAtk": 3}, by="Proficiency with the tool")
add("Bane Weapon", "Weapon", "Rare", 1, "Any Melee weapon. You gain a +1 bonus to attack and damage rolls with it. When you finish a Long Rest, choose Aberration, Beast, Celestial, Dragon, Fiend, Giant or Undead. It has 4 charges. When you hit a creature of the chosen type, spend 1 charge to deal an extra 2d6 damage of the weapon's type. It regains 1d4 charges at dawn.", fx={"atk": 1, "dmg": 1}, ch=[4, "1d4", "dawn"])
add("Byeshk Weapon", "Weapon", "Unknown", 0, "Any Melee weapon (not a Net) made of or coated with byeshk, a purple metal from Droaam and the Ironlands. It is not magical and costs 400 gp more than the normal weapon. When you hit an Aberration with it, the target takes an extra 1d6 damage of the weapon's type and cannot regain Hit Points until the start of your next turn.", xd=["Aberration: +1d6"])
add("Hungry Weapon", "Weapon", "Uncommon", 1, "Any Melee weapon, a daelkyr creation of muscle and bone. A creature that wields it without being attuned has Disadvantage on attacks with it. If you are attuned and another creature tries to wield it, thorns deal it 1d4 Piercing damage each turn. While attuned, a Bonus Action bonds it to you, and a Magic action ends the bond. While bonded you gain these. **Secure Grip.** It cannot be removed from your grasp (one hand if it is Two-Handed). **Drain Life.** When you hit, expend one Hit Die, roll it and add your Constitution modifier. The attack deals that much extra Necrotic damage and you regain the same Hit Points." + SYM)
add("Resistance Breaker", "Weapon", "Rare", 0, "Any Melee weapon with 5 charges. When you hit a creature with it, spend 1 charge to negate all of the creature's Resistances to damage until the end of your next turn. It regains 1d4 + 1 charges at dawn.", ch=[5, "1d4+1", "dawn"])
add("Silent Weapon", "Weapon", "Uncommon", 0, "Any Ranged weapon. You gain a +1 bonus to attack and damage rolls with it. When you are hidden from a creature and miss it with an attack from this weapon, the attack does not reveal your position.", fx={"atk": 1, "dmg": 1})
